import React,{useCallback,useEffect,useMemo,useState} from 'react'; import {useDispatch,useSelector} from 'react-redux'; import {Link} from 'react-router-dom'; import {logout} from '../authSlice'; import {getProfileStats} from '../../../api/userDataApi'; import Button from '../../../components/ui/Button'; import Badge from '../../../components/ui/Badge'; import ErrorState from '../../../components/ui/ErrorState'; import Skeleton from '../../../components/ui/Skeleton';
const ProfilePage=()=>{const dispatch=useDispatch();const{user}=useSelector(state=>state.auth);const[stats,setStats]=useState(null);const[loading,setLoading]=useState(true);const[error,setError]=useState(null);const joined=user?.createdAt?new Date(user.createdAt).toLocaleDateString():'N/A';const load=useCallback(async()=>{try{setLoading(true);setError(null);const response=await getProfileStats();setStats(response.data?.data?.stats||null);}catch(requestError){setError(requestError);}finally{setLoading(false);}},[]);useEffect(()=>{load();},[load]);const cards=useMemo(()=>[['Watchlist',stats?.watchlistCount??0,'/watchlist'],['Favorites',stats?.favoritesCount??0,'/favorites'],['Ratings',stats?.ratingsCount??0,null],['Reviews',stats?.reviewsCount??0,null]],[stats]);return <section className='mx-auto w-full max-w-[1100px] px-4 py-12 sm:px-6 lg:px-10'><div className='rounded-3xl border border-white/10 bg-white/[0.04] p-6 sm:p-8'><div className='flex flex-col gap-6 sm:flex-row sm:items-center'><div className='flex h-24 w-24 shrink-0 items-center justify-center overflow-hidden rounded-full border border-white/10 bg-neutral-800 text-3xl font-black text-white'>{user?.avatar?<img src={user.avatar} alt={user.name} className='h-full w-full object-cover'/>:user?.name?.charAt(0)?.toUpperCase()}</div><div className='min-w-0 flex-1'><Badge>{user?.role||'user'}</Badge><h1 className='mt-3 text-3xl font-black text-white'>{user?.name}</h1><p className='mt-1 break-all text-neutral-400'>{user?.email}</p><p className='mt-2 text-sm text-neutral-500'>Joined {joined}</p></div><Button variant='secondary' onClick={()=>dispatch(logout())}>Logout</Button></div>{loading?<div className='mt-8 grid gap-3 sm:grid-cols-4'>{Array.from({length:4}).map((_,i)=><Skeleton key={i} className='h-24'/>)}</div>:null}{!loading&&error?<div className='mt-8'><ErrorState message='Unable to load your profile activity.' onRetry={load}/></div>:null}{!loading&&!error?<><div className='mt-8 grid gap-3 sm:grid-cols-4'>{cards.map(([label,value,href])=>{const body=<><p className='text-3xl font-black text-white'>{value}</p><p className='mt-1 text-sm font-semibold text-neutral-400'>{label}</p></>;return href?<Link key={label} to={href} className='rounded-2xl border border-white/10 bg-neutral-950/50 p-4 transition hover:bg-white/[0.06]'>{body}</Link>:<div key={label} className='rounded-2xl border border-white/10 bg-neutral-950/50 p-4'>{body}</div>;})}</div><div className='mt-8 grid gap-6 lg:grid-cols-2'><div><h2 className='text-lg font-black text-white'>Recent activity</h2><div className='mt-3 space-y-2'>{stats?.recentActivity?.length?stats.recentActivity.map((item,index)=><Link to={`/${item.mediaType}/${item.tmdbId}`} key={`${item.type}-${item.tmdbId}-${index}`} className='block rounded-xl border border-white/10 bg-neutral-950/40 p-3 text-sm hover:bg-white/[0.05]'><span className='font-bold capitalize text-white'>{item.type}</span><span className='text-neutral-400'> · {item.title}{item.value?` · ${item.value}/10`:''}</span></Link>):<p className='text-sm text-neutral-500'>Your activity will appear here as you save and rate titles.</p>}</div></div><div><h2 className='text-lg font-black text-white'>Preference signals</h2><p className='mt-3 text-sm leading-6 text-neutral-400'>{stats?.favoriteGenreIds?.length?`Your recommendations currently use ${stats.favoriteGenreIds.length} strong genre signals from your saved titles and ratings.`:'Save favorites and rate titles to teach CineVerse what you enjoy.'}</p></div></div></>:null}</div></section>;}; export default ProfilePage;
